FUNCTION_BLOCK FB
VAR_INPUT
    mode : INT;
    resetBtn : BOOL;
    scanSeconds : REAL;
    tempSP : REAL;
    tempPV : REAL;
    flowPV : REAL;
    manualFlowSP : REAL;
    manualValve : REAL;
END_VAR
VAR_OUTPUT
    flowSP : REAL;
    valveCommand : REAL;
    fault : BOOL;
    normalMode : BOOL;
END_VAR
VAR
    prevResetBtn : BOOL := FALSE;
    prevMode : INT;
    firstScan : BOOL := TRUE;
    accT : REAL := 0.0;
    accF : REAL := 0.0;
    prevValveCommand : REAL := 0.0;
END_VAR
VAR
    eT : REAL;
    eF : REAL;
    trial : REAL;
END_VAR

// Detect rising edge of reset
IF resetBtn AND NOT prevResetBtn THEN
    // Reset action
    flowSP := manualFlowSP;
    valveCommand := manualValve;
    accT := 0.0;
    accF := 0.0;
    normalMode := FALSE;
ELSE
    // Normal or fault operation
    // Fault detection
    fault := (mode < 0) OR (mode > 2) OR (scanSeconds <= 0.0) OR (scanSeconds > 10.0);

    IF fault THEN
        // Fault fallback to manual
        valveCommand := manualValve;
        flowSP := manualFlowSP;
        accT := 0.0;
        accF := 0.0;
        normalMode := FALSE;
    ELSIF firstScan THEN
        // First scan initialization
        flowSP := manualFlowSP;
        valveCommand := manualValve;
        prevMode := mode;
        firstScan := FALSE;
        normalMode := FALSE;
    ELSE
        // Normal operation
        IF mode <> prevMode THEN
            // Bumpless transfer on mode change
            IF mode = 2 THEN
                // Cascade mode - maintain both outputs
                flowSP := flowSP;
                valveCommand := valveCommand;
            ELSE
                // Manual/Auto mode - flow follows manual, valve maintains
                flowSP := manualFlowSP;
                valveCommand := valveCommand;
            END_IF
            prevMode := mode;
            normalMode := FALSE;
        ELSE
            // Same mode - calculate PI control
            normalMode := TRUE;

            // Temperature loop (outer)
            eT := tempSP - tempPV;
            flowSP := flowSP + (0.2 * eT * scanSeconds) + accT;
            flowSP := LIMIT(0.0, flowSP, 50.0);
            accT := flowSP - (1.0 * eT);

            // Flow loop (inner)
            eF := flowSP - flowPV;
            valveCommand := valveCommand + (0.5 * eF * scanSeconds) + accF;
            valveCommand := LIMIT(0.0, valveCommand, 100.0);
            accF := valveCommand - (2.0 * eF);
        END_IF;
    END_IF;
END_IF;

// Store previous values for next scan
prevResetBtn := resetBtn;
